mapper.select:
SELECT ( SELECT count(*) FROM asset_info WHERE next_metering_date between now() AND date_trunc('month', now() + interval '2 months') AND (tenant_uid = #{siteUid} OR institution_uid = #{siteUid} OR hospital_uid = #{siteUid} OR site_uid = #{siteUid})
AND asset_type IN
#{item}
) AS countAssetsToMeter, ( SELECT count(*) FROM v2_work_order wo
LEFT JOIN asset_info ai ON wo.asset_uid = ai.uid
WHERE wo.status = 1 AND (wo.tenant_uid = #{siteUid} OR wo.institution_uid = #{siteUid} OR wo.hospital_uid = #{siteUid} OR wo.site_uid = #{siteUid})
AND ai.asset_type IN
#{item}
) AS countOpenIssues, ( SELECT count(*) FROM asset_info WHERE is_valid = true AND is_warranty = true AND warranty_date <= (NOW() + interval '2 months') AND (tenant_uid = #{siteUid} OR institution_uid = #{siteUid}OR hospital_uid = #{siteUid} OR site_uid = #{siteUid})
AND asset_type IN
#{item}
) AS countOutOfWarranty, ( SELECT count(*) FROM v2_pm_order po
LEFT JOIN asset_info ai ON po.asset_uid = ai.uid
WHERE po.rule_level = 2 and po.is_finished = false AND po.plan_time < (NOW() + interval '1 weeks') AND (po.tenant_uid = #{siteUid} OR po.institution_uid = #{siteUid}OR po.hospital_uid = #{siteUid} OR po.site_uid = #{siteUid})
AND ai.asset_type IN
#{item}
) AS countPmLv2, ( SELECT count(*) FROM v2_pm_order po
LEFT JOIN asset_info ai ON po.asset_uid = ai.uid
WHERE po.rule_level = 3 AND po.is_finished = false AND po.plan_time < (NOW() + interval '1 weeks') AND (po.tenant_uid = #{siteUid} OR po.institution_uid = #{siteUid}OR po.hospital_uid = #{siteUid} OR po.site_uid = #{siteUid})
AND ai.asset_type IN
#{item}
) AS countPmLv3
